def pair_independence(left,right):
    gates={"eligible_roles":left.get("frozen_role")==right.get("frozen_role")=="COMMON_CONSTRAINT_CANDIDATE" and left.get("qualified_for_task_role") is True and right.get("qualified_for_task_role") is True,"distinct_lineage":bool(left.get("lineage_id") and right.get("lineage_id") and left["lineage_id"]!=right["lineage_id"]),"distinct_correlation_group":bool(left.get("correlation_group_id") and right.get("correlation_group_id") and left["correlation_group_id"]!=right["correlation_group_id"]),"target_exposure_permitted":left.get("target_exposed") is False and right.get("target_exposed") is False,"source_internal_permitted":left.get("source_internal_validation") is False and right.get("source_internal_validation") is False,"consumed_comparison_permitted":left.get("consumed_comparison_conflict") is False and right.get("consumed_comparison_conflict") is False,"provenance_complete":left.get("provenance_complete") is True and right.get("provenance_complete") is True,"rights_permit_analysis":left.get("rights_permit_analysis") is True and right.get("rights_permit_analysis") is True,"ewp_calibration_independent":left.get("ewp_calibration_independent") is True and right.get("ewp_calibration_independent") is True,"distinct_experiment":left.get("experiment_id")!=right.get("experiment_id")}
    return {"left_support_id":left["support_id"],"right_support_id":right["support_id"],"gates":gates,"independent_for_common_constraint":all(gates.values()),"context_roles_preserved":True}
